package com.skycraft.society;

import java.util.Locale;

/**
 * Clothing layers of townsfolk ({@code textures/entity/society/npc/outfit/<id>_<variant>_<m|f>.png}, generated by
 * {@code tools/textures/society.py}). The ordinal is stored in {@link NpcLook}, so new outfits go at the end and the
 * Python {@code OUTFITS} list must keep the same order.
 */
public enum Outfit {
    FARM, FINE, MERCHANT, BLACKSMITH, PRIEST, MAGE, BEGGAR, JARL, STEWARD, CHILD, MINER, HUNTER, BARD, INNKEEPER, COURIER,
    LUMBERJACK, SCHOLAR, FISHER, THALMOR, IMPERIAL_SOLDIER, STORMCLOAK_SOLDIER, FORSWORN, VAMPIRE, NECROMANCER, ASSASSIN,
    THUG, THIEF, ADVENTURER, HOUSECARL, NORD_FUR, DUNMER, REDGUARD, KHAJIIT, CARAVAN, ARGONIAN, IMPERIAL, ALTMER, BOSMER,
    BRETON, ORC;

    public static final Outfit[] VALUES = values();
    /** Colour variants per outfit. */
    public static final int VARIANTS = 3;

    public final String id = name().toLowerCase(Locale.ROOT);

    public static Outfit byOrdinal(int i) {
        return VALUES[Math.floorMod(i, VALUES.length)];
    }

    /** The everyday clothes of a race's homeland. */
    public static Outfit cultural(NpcNames.Race race) {
        return switch (race) {
            case NORD -> NORD_FUR;
            case IMPERIAL -> IMPERIAL;
            case BRETON -> BRETON;
            case REDGUARD -> REDGUARD;
            case ALTMER -> ALTMER;
            case BOSMER -> BOSMER;
            case DUNMER -> DUNMER;
            case KHAJIIT -> KHAJIIT;
            case ARGONIAN -> ARGONIAN;
            case ORC -> ORC;
        };
    }
}
